    set_code text, set_name text, series_name text, release_date date,
    advertised_card_count integer, checklist_source_url text, checklist_scope_note text, cards jsonb
  )
), inserted_sets as (
  insert into public.card_sets (
    series_name,set_name,set_code,language,release_date,advertised_card_count,
    checklist_source_url,checklist_scope_note,is_public
  )
  select series_name,set_name,set_code,'FR',release_date,advertised_card_count,
         checklist_source_url,checklist_scope_note,false
  from input_sets
  on conflict (set_name,language) do nothing
  returning id
), resolved_sets as (
  select s.id,s.set_code
  from public.card_sets s
  join input_sets i on i.set_name=s.set_name and s.language='FR'
), card_rows as (
  select r.id as card_set_id, c.card->>'local_id' as collector_number,
         c.card->>'card_name' as card_name, c.ordinality::integer as guide_order
  from resolved_sets r
  join input_sets i on i.set_code=r.set_code
  cross join lateral jsonb_array_elements(i.cards) with ordinality as c(card,ordinality)
)
insert into public.cards (card_set_id,collector_number,card_name,guide_order)
select card_set_id,collector_number,card_name,guide_order
from card_rows
on conflict (card_set_id,collector_number) do nothing;
